// A zero-row PostgreSQL executeQuery can emit {success:true}. Never send it to Meta.
const items=$input.all();
if (items.length===0) return [];
if (items.length!==1) throw Error('claim_ambigu_plusieurs_lignes');
const row=items[0]?.json;
if (!row || Object.keys(row).length===0 || (Object.keys(row).length===1 && row.success===true)) return [];
const raw=row.id;
const text=typeof raw==='string'?raw.trim():typeof raw==='number'&&Number.isSafeInteger(raw)?String(raw):'';
if (!/^(?:0*[1-9]\d*)$/.test(text)) throw Error('claim_id_invalide');
const id=text.replace(/^0+/,'');
if (id.length>19 || (id.length===19 && id>'9223372036854775807')) throw Error('claim_id_hors_plage');
if (row.status!=='publishing'||row.fb_state!=='submitting'||row.ig_state!=='creating'||
    row.human_decision!=='approved'||!row.approved_at||!row.decided_at) throw Error('claim_non_approuve_ou_etat_invalide');
if (row.facebook_post_id!==null && row.facebook_post_id!==undefined) throw Error('facebook_deja_reference');
if (typeof row.source_id!=='string'||!row.source_id.trim()) throw Error('claim_source_absente');
if (typeof row.image_url!=='string'||!/^https:\/\/www\.cuisine-du-cambodge\.com\/social-assets\/[a-z0-9-]+\.jpg$/.test(row.image_url)) throw Error('claim_image_url_invalide');
if (typeof row.facebook_caption!=='string'||!row.facebook_caption.trim()||
    typeof row.instagram_caption!=='string'||!row.instagram_caption.trim()) throw Error('claim_legendes_absentes');
return items;
